local a={}a.CFG={degPerRow=5,degPerStep=7,maxStep=3,wingSpan=5,circleCh="O",wingCh="-",tipCh="|"}local function b(c)return math.floor(c+0.5)end;local function d(e,f,g)if e<f then return f elseif e>g then return g else return e end end;function a.pitchRows(h,i)i=i or a.CFG;return b((h or 0)/i.degPerRow)end;function a.bankStep(j,i)i=i or a.CFG;return d(b((j or 0)/i.degPerStep),-i.maxStep,i.maxStep)end;function a.craftCells(h,j,k,l,i)i=i or a.CFG;local m={}local n=math.ceil(k/2)local o=math.ceil(l/2)-a.pitchRows(h,i)local p=a.bankStep(j,i)local function q(c,r,s)if c>=1 and c<=k and r>=1 and r<=l then m[#m+1]={x=c,y=r,ch=s}end end;q(n,o,i.circleCh)for t=-1,1,2 do local u=t*p;for v=1,i.wingSpan do local w=v/i.wingSpan;local x=b(u*w)local c=n+t*v;local s=v==i.wingSpan and i.tipCh or i.wingCh;q(c,o+x,s)end end;return m end;return a